struct Retangulo {
    largura: u32,
    altura: u32,
}

impl Retangulo {
    fn area(&self) -> u32 {
        self.largura * self.altura
    }
}

fn main() {
    let r = Retangulo { largura: 10, altura: 5 };
    println!("Área = {}", r.area());
}

